      whatIsLocal: {
        id: 'what-is-local',
        title: 'Was "lokale Sicherheitskamera" wirklich bedeutet',
        content: '**"Lokal" ist nicht eine Sache — es kann lokalen Speicher, lokales Streaming, lokale KI-Verarbeitung oder lokale Steuerung bedeuten, und eine Kamera kann einige davon haben, ohne die anderen.** Dieser Leitfaden bewertet jede Marke in allen vier Punkten separat auf einer 4-Stufen-Skala, statt eines vagen "lokal"-Labels.',
        items: [
          'Lokaler Speicher: Aufnahmen werden auf eine SD-Karte oder einen lokalen NVR/Hub geschrieben, statt (oder zusätzlich zu) der Cloud.',
          'Lokales Streaming: Die Kamera bietet ein offenes Protokoll (RTSP/ONVIF), sodass Frigate oder Home Assistant den Live-Feed direkt abrufen können, ohne über die Hersteller-Cloud zu gehen.',
          'Lokale KI: Objekt-/Personenerkennung läuft auf lokaler Hardware (GPU, Intel-iGPU oder ein Beschleuniger wie Hailo), nicht auf den Servern des Herstellers.',
          'Lokale Steuerung: Die Kamera kann vollständig im lokalen Netzwerk angesehen, konfiguriert und verwaltet werden, ohne ein verpflichtendes Herstellerkonto.',
          'Stufe 4 — Wirklich lokal: lokaler Speicher UND lokales Streaming (RTSP/ONVIF) UND funktioniert ohne verpflichtendes Cloud-Konto. Beispiel: Reolink-PoE-Linie, Amcrest-PoE-Linie.',
          'Stufe 3 — Größtenteils lokal: lokaler Speicher und zuverlässige lokale Aufzeichnung, aber die Konsole/App hat noch cloud-verknüpfte Kontoelemente. Beispiel: UniFi Protect.',
          'Stufe 2 — Hybrid: lokaler Speicher funktioniert gut, aber das offene Streaming-Protokoll fehlt oder ist für Drittanbieterzugriff derzeit eingeschränkt. Beispiel: Aqara G5 Pro (RTSP funktioniert, Matter-Kamerafunktion in Home Assistant eingeschränkt), Eufy (starker lokaler Speicher, kein offenes RTSP).',
          'Stufe 1 — Cloud-first: lokaler Speicher ist bestenfalls eine Backup-Funktion; der primäre Zugriffsweg ist die Hersteller-App/Cloud. Auf dieser Seite keine primäre Empfehlung.',
        ],
      },
