      whatIsLocal: {
        id: 'what-is-local',
        title: 'Qué significa realmente "cámara de seguridad local"',
        content: '**"Local" no es una sola cosa — puede significar almacenamiento local, streaming local, procesamiento de IA local o control local, y una cámara puede tener algunas de estas capacidades sin las otras.** Esta guía califica cada marca por separado en estos cuatro aspectos usando una escala de 4 niveles, en lugar de una etiqueta vaga de "local".',
        items: [
          'Almacenamiento local: las grabaciones se escriben en una tarjeta SD o un NVR/hub local en lugar de (o además de) la nube.',
          'Streaming local: la cámara expone un protocolo abierto (RTSP/ONVIF) para que Frigate o Home Assistant puedan obtener la señal en vivo directamente, sin pasar por la nube del fabricante.',
          'IA local: la detección de objetos/personas se ejecuta en hardware local (una GPU, una iGPU Intel, o un acelerador como Hailo), no en los servidores del fabricante.',
          'Control local: la cámara puede visualizarse, configurarse y gestionarse totalmente en la red local, sin una cuenta obligatoria del fabricante.',
          'Nivel 4 — Verdaderamente local: almacenamiento local Y streaming local (RTSP/ONVIF) Y funciona sin cuenta en la nube obligatoria. Ejemplo: línea PoE de Reolink, línea PoE de Amcrest.',
          'Nivel 3 — Mayormente local: almacenamiento local y grabación local fiable, pero la consola/app aún tiene elementos de cuenta vinculados a la nube. Ejemplo: UniFi Protect.',
          'Nivel 2 — Híbrido: el almacenamiento local funciona bien, pero el protocolo de streaming abierto falta o está actualmente limitado para acceso de terceros. Ejemplo: Aqara G5 Pro (RTSP funciona, soporte de cámara Matter limitado en Home Assistant), Eufy (almacenamiento local sólido, sin RTSP abierto).',
          'Nivel 1 — Nube primero: el almacenamiento local es como mucho una función de respaldo; la vía de acceso principal es la app/nube del fabricante. No se cubre como opción principal en esta página.',
        ],
      },
