        title: 'Lo que Frigate realmente necesita de una cámara',
        content: '**La mejor cámara para Frigate no es necesariamente la "mejor" cámara en general — Frigate necesita específicamente una señal RTSP estable, no la resolución más vistosa ni la mejor app móvil.** Esto coincide con los requisitos ya cubiertos en la guía de Frigate presente en este sitio.',
        items: [
          'Señal RTSP abierta: el único requisito estricto — sin ella, Frigate no puede obtener la señal en absoluto.',
          'Conexión estable: PoE es más fiable que Wi-Fi para la señal continua que Frigate necesita para la detección en tiempo real.',
          'Disponibilidad de subseñal: una segunda señal de menor resolución que el modelo de detección analiza, dejando la señal principal completa reservada para la grabación — la mayoría de las cámaras PoE con RTSP lo admiten.',
          'ONVIF (útil, no obligatorio): facilita el descubrimiento de cámaras y el control PTZ desde Frigate/Home Assistant, pero RTSP por sí solo basta para la detección básica.',
          'Autenticación local: evite cámaras que fuercen cada solicitud de señal a través de un relé en la nube incluso para el acceso en la red local — eso anula el propósito de una configuración local.',
          'Consulte la guía de cámaras de seguridad con IA local y Frigate para el proceso de configuración completo, las opciones de aceleración de hardware (Hailo, iGPU Intel) y la integración con Home Assistant una vez elegidas las cámaras.',
        ],
