      architecture: {
        id: 'architecture',
        title: 'Arquitectura del sistema: cómo se conecta todo',
        content: 'Un sistema de cámaras locales es una cadena — cada paso permanece en su red local, sin ningún viaje de ida y vuelta a la nube en ningún punto:',
        codeBlock: 'Cámara PoE  --señal RTSP-->  Frigate (IA local: detección de persona / coche / animal)\n  --MQTT / API-->  Home Assistant\n  --automatización-->  Alerta local (notificación por red local, altavoz, luz)\n\nNinguna etapa de esta cadena requiere conexión a internet una vez configurada.',
        items: [
          'Cámara: captura el video y lo expone como señal RTSP — este es el único enlace estricto de la cadena.',
          'Frigate: obtiene la señal RTSP, ejecuta detección de objetos local (persona/coche/animal) en una GPU, iGPU Intel o acelerador Hailo, y guarda los clips localmente.',
          'Home Assistant: recibe los eventos de detección de Frigate a través de la red local y activa automatizaciones.',
          'Alerta: una notificación local, luz o acción de altavoz — toda la cadena puede funcionar con el router desconectado de internet, una vez completadas la configuración inicial y el firmware.',
        ],
      },
