      faqSection: {
        id: 'faq',
        title: 'Preguntas frecuentes',
        faqs: [
          { q: '¿Qué cámara funciona sin suscripción?', a: 'Reolink, Amcrest, UniFi Protect, Eufy y el Camera Hub G5 Pro de Aqara admiten grabación local sin suscripción obligatoria para uso básico — verifique las condiciones actuales del modelo exacto antes de comprar. [Ver el precio actual de Reolink](https://reolink.com/product/rlc-810a/).' },
          { q: '¿Qué cámara es mejor para Frigate?', a: 'Las líneas PoE de Amcrest y Reolink tienen el soporte RTSP + ONVIF confirmado más consistente, lo que las hace las cámaras más compatibles con Frigate de esta página. [Ver la línea PoE actual de Amcrest](https://amcrest.com/ip-cameras/poe-cameras.html).' },
          { q: '¿Qué cámaras admiten RTSP?', a: 'Reolink (todos los modelos PoE/Wi-Fi actuales), Amcrest (toda la línea PoE) y el Camera Hub G5 Pro de Aqara (confirmado) admiten RTSP. UniFi y Eufy no exponen una señal RTSP abierta.' },
          { q: '¿Qué cámaras admiten ONVIF?', a: 'Amcrest (Profile S/T, y G/M en algunos modelos) y Reolink (Profile S) confirman soporte ONVIF. UniFi usa su propio protocolo propietario; Eufy no tiene ONVIF oficial; el G5 Pro de Aqara no admite ONVIF (solo RTSP).' },
          { q: '¿Funciona Reolink con Home Assistant?', a: 'Sí — mediante su señal RTSP (a través de Frigate o una integración genérica de cámara) o la integración propia de Reolink con Home Assistant para modelos seleccionados; verifique la compatibilidad actual de su modelo específico antes de comprar.' },
          { q: '¿Funciona Reolink con Frigate?', a: 'Sí — RTSP está confirmado en todos los modelos Reolink PoE/Wi-Fi actuales, que es el requisito principal de Frigate.' },
          { q: '¿Es UniFi Protect completamente local?', a: 'La grabación y la visualización esencial son completamente locales — cada cámara graba en un NVR local sin cuota recurrente —, pero el protocolo de la cámara en sí es propietario, no RTSP/ONVIF abierto, y algunas funciones de configuración/app están vinculadas a la nube. [Ver el precio actual del UNVR](https://store.ui.com/us/en/products/unvr).' },
          { q: '¿Es Eufy realmente local?', a: 'El almacenamiento es genuinamente local (hasta 16 TB en el HomeBase, sin cuota mensual), pero no hay un protocolo de streaming abierto oficial — "local" aquí significa almacenamiento local, no acceso de streaming local para software de terceros como Frigate.' },
          { q: '¿Pueden estas cámaras funcionar sin acceso a internet?', a: 'Sí, una vez configuradas — el almacenamiento local y la detección de Frigate basada en RTSP funcionan totalmente en la red local. La configuración inicial y las actualizaciones de firmware de la mayoría de las marcas aún requieren conexión a internet al menos una vez.' },
          { q: '¿Cuál es la mejor cámara PoE para una configuración de NVR local?', a: 'La línea PoE de Amcrest, dado su amplio soporte ONVIF Profile S/T para software NVR de terceros (Blue Iris, Synology Surveillance Station), o Reolink si prefiere un emparejamiento con NVR listo para usar más sencillo.' },
          { q: '¿Cuánto almacenamiento necesito para cuatro cámaras 4K?', a: 'Aproximadamente 1–4 TB para una a dos semanas de grabación continua en 4K, dependiendo del códec (H.265 usa notablemente menos que H.264), la tasa de fotogramas y cuánta grabación solo por movimiento frente a continua configure — dimensione el almacenamiento después de probar sus ajustes reales, no a partir de una cifra genérica.' },
          { q: '¿Cuántas cámaras puede manejar Frigate?', a: 'Depende de su hardware de detección, no de una cifra fija — una iGPU Intel maneja un puñado de cámaras, y un acelerador Hailo-8L o Hailo-8 escala más allá. Vea la sección de capacidad de hardware anterior y la guía de hardware local para el dimensionamiento.' },
          { q: '¿Es la detección de IA local tan precisa como la IA en la nube?', a: 'La detección local moderna (Frigate con un acelerador capaz) es generalmente comparable para categorías comunes como detección de personas/vehículos/animales. Los servicios en la nube pueden tener ventaja en un reconocimiento más especializado, pero eso implica la dependencia de la nube que esta guía busca evitar.' },
          { q: '¿Necesito un Coral TPU para Frigate en 2026?', a: 'No — Frigate ya no recomienda el Google Coral para montajes nuevos. Actualmente dirige a los nuevos usuarios hacia un acelerador Hailo-8L o Hailo-8 M.2, o la iGPU Intel integrada de un equipo anfitrión vía OpenVINO para cargas más ligeras.' },
        ],
      },
