      whatIsLocal: {
        id: 'what-is-local',
        title: 'O que "câmera de segurança local" realmente significa',
        content: '**"Local" não é uma coisa só — pode significar armazenamento local, streaming local, processamento de IA local ou controle local, e uma câmera pode ter algumas dessas capacidades sem as outras.** Este guia avalia cada marca separadamente nesses quatro pontos usando uma escala de 4 níveis, em vez de um rótulo vago de "local".',
        items: [
          'Armazenamento local: as gravações são escritas em um cartão SD ou em um NVR/hub local em vez de (ou além de) a nuvem.',
          'Streaming local: a câmera expõe um protocolo aberto (RTSP/ONVIF) para que Frigate ou Home Assistant possam obter o sinal ao vivo diretamente, sem passar pela nuvem do fabricante.',
          'IA local: a detecção de objetos/pessoas roda em hardware local (uma GPU, uma iGPU Intel, ou um acelerador como o Hailo), não nos servidores do fabricante.',
          'Controle local: a câmera pode ser visualizada, configurada e gerenciada totalmente na rede local, sem uma conta obrigatória do fabricante.',
          'Nível 4 — Verdadeiramente local: armazenamento local E streaming local (RTSP/ONVIF) E funciona sem conta obrigatória na nuvem. Exemplo: linha PoE da Reolink, linha PoE da Amcrest.',
          'Nível 3 — Majoritariamente local: armazenamento local e gravação local confiável, mas o console/app ainda tem elementos de conta vinculados à nuvem. Exemplo: UniFi Protect.',
          'Nível 2 — Híbrido: o armazenamento local funciona bem, mas o protocolo de streaming aberto está ausente ou atualmente limitado para acesso de terceiros. Exemplo: Aqara G5 Pro (RTSP funciona, suporte a câmera Matter limitado no Home Assistant), Eufy (armazenamento local forte, sem RTSP aberto).',
          'Nível 1 — Nuvem em primeiro lugar: o armazenamento local é, no máximo, um recurso de backup; o caminho principal de acesso é o app/nuvem do fabricante. Não coberto como escolha principal nesta página.',
        ],
      },
