      faqSection: {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          { q: 'Qual câmera funciona sem assinatura?', a: 'Reolink, Amcrest, UniFi Protect, Eufy e o Camera Hub G5 Pro da Aqara suportam gravação local sem assinatura obrigatória para uso básico — verifique os termos atuais do modelo exato antes de comprar. [Ver preço atual da Reolink](https://reolink.com/product/rlc-810a/).' },
          { q: 'Qual câmera é melhor para o Frigate?', a: 'As linhas PoE da Amcrest e da Reolink têm o suporte a RTSP + ONVIF confirmado mais consistente, tornando-as as câmeras mais amigáveis ao Frigate nesta página. [Ver a linha PoE atual da Amcrest](https://amcrest.com/ip-cameras/poe-cameras.html).' },
          { q: 'Quais câmeras suportam RTSP?', a: 'Reolink (todos os modelos PoE/Wi-Fi atuais), Amcrest (toda a linha PoE) e o Camera Hub G5 Pro da Aqara (confirmado) suportam RTSP. UniFi e Eufy não expõem um sinal RTSP aberto.' },
          { q: 'Quais câmeras suportam ONVIF?', a: 'Amcrest (Profile S/T, e G/M em alguns modelos) e Reolink (Profile S) confirmam suporte a ONVIF. UniFi usa seu próprio protocolo proprietário; Eufy não tem ONVIF oficial; o G5 Pro da Aqara não suporta ONVIF (apenas RTSP).' },
          { q: 'A Reolink funciona com o Home Assistant?', a: 'Sim — via seu sinal RTSP (através do Frigate ou de uma integração de câmera genérica) ou da integração própria da Reolink com o Home Assistant para modelos selecionados; verifique a compatibilidade atual do seu modelo específico antes de comprar.' },
          { q: 'A Reolink funciona com o Frigate?', a: 'Sim — o RTSP é confirmado em todos os modelos Reolink PoE/Wi-Fi atuais, que é o requisito principal do Frigate.' },
          { q: 'O UniFi Protect é totalmente local?', a: 'A gravação e a visualização essencial são totalmente locais — cada câmera grava em um NVR local sem taxa recorrente —, mas o protocolo da câmera em si é proprietário, não RTSP/ONVIF aberto, e alguns recursos de configuração/app são vinculados à nuvem. [Ver preço atual do UNVR](https://store.ui.com/us/en/products/unvr).' },
          { q: 'A Eufy é realmente local?', a: 'O armazenamento é genuinamente local (até 16 TB no HomeBase, sem mensalidade), mas não há um protocolo de streaming aberto oficial — "local" aqui significa armazenamento local, não acesso de streaming local para softwares de terceiros como o Frigate.' },
          { q: 'Essas câmeras podem funcionar sem acesso à internet?', a: 'Sim, depois de configuradas — o armazenamento local e a detecção do Frigate baseada em RTSP funcionam inteiramente na rede local. A configuração inicial e as atualizações de firmware da maioria das marcas ainda exigem uma conexão com a internet pelo menos uma vez.' },
          { q: 'Qual é a melhor câmera PoE para uma configuração de NVR local?', a: 'A linha PoE da Amcrest, dado seu amplo suporte a ONVIF Profile S/T para software de NVR de terceiros (Blue Iris, Synology Surveillance Station), ou a Reolink se você preferir um emparelhamento de NVR pronto para usar mais simples.' },
          { q: 'Quanto armazenamento preciso para quatro câmeras 4K?', a: 'Aproximadamente 1–4 TB para uma a duas semanas de gravação contínua em 4K, dependendo do codec (o H.265 usa consideravelmente menos que o H.264), da taxa de quadros e de quanto você configura gravação apenas por movimento versus contínua — dimensione o armazenamento depois de testar suas configurações reais, não a partir de um número genérico.' },
          { q: 'Quantas câmeras o Frigate consegue lidar?', a: 'Depende do seu hardware de detecção, não de um número fixo — uma iGPU Intel lida com um punhado de câmeras, e um acelerador Hailo-8L ou Hailo-8 escala além disso. Veja a seção de capacidade de hardware acima e o guia de hardware local para o dimensionamento.' },
          { q: 'A detecção de IA local é tão precisa quanto a IA na nuvem?', a: 'A detecção local moderna (Frigate com um acelerador capaz) geralmente é comparável para categorias comuns como detecção de pessoas/veículos/animais. Serviços na nuvem podem ter vantagem em reconhecimento mais especializado, mas isso vem com a dependência da nuvem que este guia busca evitar.' },
          { q: 'Preciso de um Coral TPU para o Frigate em 2026?', a: 'Não — o Frigate não recomenda mais o Google Coral para montagens novas. Atualmente ele direciona novos usuários para um acelerador Hailo-8L ou Hailo-8 M.2, ou a iGPU Intel integrada de um host via OpenVINO para cargas mais leves.' },
        ],
      },
