        content: '**"المحلية" ليست شيئًا واحدًا — يمكن أن تعني تخزينًا محليًا أو بثًا محليًا أو معالجة ذكاء اصطناعي محلية أو تحكمًا محليًا، وقد تمتلك الكاميرا بعض هذه الخصائص دون غيرها.** يقيّم هذا الدليل كل علامة تجارية بشكل منفصل في هذه النقاط الأربع باستخدام مقياس من 4 مستويات، بدلًا من وصف غامض لكلمة "محلية".',
