          'الذكاء الاصطناعي المحلي: يعمل الكشف عن الأجسام/الأشخاص على جهاز محلي (وحدة معالجة رسومات GPU، أو iGPU من Intel، أو مسرّع مثل Hailo)، وليس على خوادم الشركة المصنّعة.',
