        title: 'ما الذي يحتاجه Frigate فعليًا من الكاميرا',
        content: '**أفضل كاميرا لـ Frigate ليست بالضرورة "أفضل" كاميرا بشكل عام — يحتاج Frigate تحديدًا إلى بث RTSP مستقر، وليس إلى أعلى دقة أو أفضل تطبيق للهاتف.** يتوافق هذا مع المتطلبات المذكورة بالفعل في دليل Frigate الموجود على هذا الموقع.',
